            private static ushort ScaleDisplayAxis(double value, double min, double max, int tabletMax)
            {
                if (max <= min)
                    return 0;

                return (ushort)Math.Clamp((int)Math.Round((value - min) / (max - min) * tabletMax), 0, tabletMax);
            }

            private static (double MinX, double MinY, double MaxX, double MaxY) GetVirtualDisplayBounds()
            {
                var displays = new uint[16];
                var result = CoreGraphics.CGGetActiveDisplayList((uint)displays.Length, displays, out var displayCount);
                if (result != 0 || displayCount == 0)
                    return (0, 0, MaxX, MaxY);

                var minX = double.MaxValue;
                var minY = double.MaxValue;
                var maxX = double.MinValue;
                var maxY = double.MinValue;
                for (var i = 0; i < displayCount; i++)
                {
                    var bounds = CoreGraphics.CGDisplayBounds(displays[i]);
                    minX = Math.Min(minX, bounds.Origin.X);
                    minY = Math.Min(minY, bounds.Origin.Y);
                    maxX = Math.Max(maxX, bounds.Origin.X + bounds.Size.Width);
                    maxY = Math.Max(maxY, bounds.Origin.Y + bounds.Size.Height);
                }

                return (minX, minY, maxX, maxY);
            }

