using System.Numerics;
using OpenTabletDriver.Plugin.Attributes;
using OpenTabletDriver.Plugin.Platform.Pointer;
using OpenTabletDriver.Plugin.Tablet;

namespace OpenTabletDriver.Plugin.Output
{
    /// <summary>
    /// An absolutely positioned output mode.
    /// </summary>
    [PluginIgnore]
    public abstract class AbsoluteOutputMode : OutputMode
    {
        private Vector2 min, max;
        private Area? outputArea, inputArea;

        /// <summary>
        /// The area in which the tablet's input is transformed to.
        /// </summary>
        public Area? Input
        {
            set
            {
                this.inputArea = value;
                this.TransformationMatrix = CreateTransformationMatrix();
            }
            get => this.inputArea;
        }

        /// <summary>
        /// The area in which the final processed output is transformed to.
        /// </summary>
        public Area? Output
        {
            set
            {
                this.outputArea = value;
                this.TransformationMatrix = CreateTransformationMatrix();
            }
            get => this.outputArea;
        }

        /// <summary>
        /// The class in which the final absolute positioned output is handled.
        /// </summary>
        public abstract IAbsolutePointer? Pointer { set; get; }

        /// <summary>
        /// Whether to clip all tablet inputs to the assigned areas.
        /// </summary>
        /// <remarks>
        /// If false, input outside the area can escape the assigned areas, but still will be transformed.
        /// If true, input outside the area will be clipped to the edges of the assigned areas.
        /// </remarks>
        public bool AreaClipping { set; get; }

        /// <summary>
        /// Whether to stop accepting input outside the assigned areas.
        /// </summary>
        /// <remarks>
        /// If true, <see cref="AreaClipping"/> is automatically implied true.
        /// </remarks>
        public bool AreaLimiting { set; get; }

        protected override Matrix3x2 CreateTransformationMatrix()
        {
            if (Input != null && Output != null && Tablet != null)
            {
                var transform = CalculateTransformation(Input, Output, Tablet.Properties.Specifications.Digitizer);

                var halfDisplayWidth = Output?.Width / 2 ?? 0;
                var halfDisplayHeight = Output?.Height / 2 ?? 0;

                var minX = Output?.Position.X - halfDisplayWidth ?? 0;
                var maxX = Output?.Position.X + Output?.Width - halfDisplayWidth ?? 0;
                var minY = Output?.Position.Y - halfDisplayHeight ?? 0;
                var maxY = Output?.Position.Y + Output?.Height - halfDisplayHeight ?? 0;

                this.min = new Vector2(minX, minY);
                this.max = new Vector2(maxX, maxY);

                return transform;
            }
            else
            {
                return Matrix3x2.Identity;
            }
        }

        protected static Matrix3x2 CalculateTransformation(Area input, Area output, DigitizerSpecifications digitizer)
        {
            // Convert raw tablet data to millimeters
            var res = Matrix3x2.CreateScale(
                digitizer.Width / digitizer.MaxX,
                digitizer.Height / digitizer.MaxY);

            // Translate to the center of input area
            res *= Matrix3x2.CreateTranslation(
                -input.Position.X, -input.Position.Y);

            // Apply rotation
            res *= Matrix3x2.CreateRotation(
                (float)(-input.Rotation * System.Math.PI / 180));

            // Scale millimeters to pixels
            res *= Matrix3x2.CreateScale(
                output.Width / input.Width, output.Height / input.Height);

            // Translate output to virtual screen coordinates
            res *= Matrix3x2.CreateTranslation(
                output.Position.X, output.Position.Y);

            return res;
        }

        /// <summary>
        /// Transposes, transforms, and performs all absolute positioning calculations to a <see cref="IAbsolutePositionReport"/>.
        /// </summary>
        /// <param name="report">The <see cref="IAbsolutePositionReport"/> in which to transform.</param>
        protected override IAbsolutePositionReport? Transform(IAbsolutePositionReport report)
        {
            // Apply transformation
            var pos = Vector2.Transform(report.Position, this.TransformationMatrix);

            // Clipping to display bounds
            var clippedPoint = Vector2.Clamp(pos, this.min, this.max);
            if (AreaLimiting && clippedPoint != pos)
                return null;

            if (AreaClipping)
                pos = clippedPoint;

            report.Position = pos;

            return report;
        }

        protected override void OnOutput(IDeviceReport report)
        {
            // this should be ordered from least to most chance of having a
            // dependency to another pointer property.
            if (report is IProximityReport proximityReport && Pointer is IHoverDistanceHandler hoverDistanceHandler)
                hoverDistanceHandler.SetHoverDistance(proximityReport.HoverDistance);
            if (report is IEraserReport eraserReport && Pointer is IEraserHandler eraserHandler)
                eraserHandler.SetEraser(eraserReport.Eraser);
            if (report is ITiltReport tiltReport && Pointer is ITiltHandler tiltHandler && !DisableTilt)
                tiltHandler.SetTilt(tiltReport.Tilt);
            if (report is ITabletReport tabletReport && Pointer is IPressureHandler pressureHandler &&
                !DisablePressure && Tablet?.Properties.Specifications.Pen != null)
                pressureHandler.SetPressure(tabletReport.Pressure / (float)Tablet.Properties.Specifications.Pen.MaxPressure);

            // make sure to set the position last
            if (Pointer != null && report is IAbsolutePositionReport absReport)
                Pointer.SetPosition(absReport.Position);
            if (Pointer is ISynchronousPointer synchronousPointer)
            {
                if (report is OutOfRangeReport)
                    synchronousPointer.Reset();
                synchronousPointer.Flush();
            }
        }
    }
}
using System;
using System.Numerics;
using OpenTabletDriver.Plugin.Attributes;
using OpenTabletDriver.Plugin.Platform.Pointer;
using OpenTabletDriver.Plugin.Tablet;
using OpenTabletDriver.Plugin.Timing;

namespace OpenTabletDriver.Plugin.Output
{
    /// <summary>
    /// A relatively positioned output mode.
    /// </summary>
    [PluginIgnore]
    public abstract class RelativeOutputMode : OutputMode
    {
        private HPETDeltaStopwatch stopwatch = new HPETDeltaStopwatch();
        private Vector2? lastTransformedPos;
        private Vector2 lastReadPos;
        private bool outOfRange;

        // for handling detection of low resetTimes
        private uint _resets;
        private bool _warnedBadResets;

        /// <summary>
        /// The class in which the final relative positioned output is handled.
        /// </summary>
        public abstract IRelativePointer? Pointer { set; get; }

        private Vector2 sensitivity;

        /// <summary>
        /// The sensitivity vector in which input will be transformed.
        /// <remarks>
        /// This sensitivity is in mm/px.
        /// </remarks>
        /// </summary>
        public Vector2 Sensitivity
        {
            set
            {
                this.sensitivity = value;
                this.TransformationMatrix = CreateTransformationMatrix();
            }
            get => this.sensitivity;
        }

        private float rotation;
        private TimeSpan _resetTime;

        /// <summary>
        /// The angle of rotation to be applied to the input.
        /// </summary>
        public float Rotation
        {
            set
            {
                this.rotation = value;
                this.TransformationMatrix = CreateTransformationMatrix();
            }
            get => this.rotation;
        }

        /// <summary>
        /// The delay in which to reset the last known position in relative positioning.
        /// </summary>
        public TimeSpan ResetTime
        {
            set
            {
                _resetTime = value;
                _resets = 0;
                _warnedBadResets = false;
            }
            get => _resetTime;
        }

        protected override Matrix3x2 CreateTransformationMatrix()
        {
            var transform = Matrix3x2.CreateRotation(
                (float)(-Rotation * System.Math.PI / 180));

            var digitizer = Tablet?.Properties.Specifications.Digitizer;
            return transform *= Matrix3x2.CreateScale(
                sensitivity.X * ((digitizer?.Width / digitizer?.MaxX) ?? 0.01f),
                sensitivity.Y * ((digitizer?.Height / digitizer?.MaxY) ?? 0.01f));
        }

        public override void Read(IDeviceReport deviceReport)
        {
            // intercept positional reports
            if (deviceReport is IAbsolutePositionReport report)
            {
                var deltaTime = stopwatch.Restart();

                // reset origin when exceeding the reset delay
                if (deltaTime > ResetTime)
                {
                    outOfRange = true;
                    lastTransformedPos = null;
                    _resets++;
                }
                else _resets = 0;

                if (!_warnedBadResets &&
                    (_warnedBadResets =
                        _resets > 10))
                    Log.WriteNotify("RelativeOutputMode",
                        $"Position reset spam detected - the configured reset time ({ResetTime.TotalMilliseconds} ms) is likely too low",
                        LogLevel.Warning);

                // skip duplicate reports sent by tablets right after going into
                // range from an out of range state.
                if (outOfRange && report.Position == lastReadPos)
                    return;

                outOfRange = false;
                lastReadPos = report.Position;
            }
            else if (deviceReport is OutOfRangeReport)
            {
                outOfRange = true;
            }

            base.Read(deviceReport);
        }

        protected override IAbsolutePositionReport Transform(IAbsolutePositionReport report)
        {
            var pos = Vector2.Transform(report.Position, TransformationMatrix);
            var delta = pos - lastTransformedPos;

            lastTransformedPos = pos;
            report.Position = delta.GetValueOrDefault();

            return report;
        }

        protected override void OnOutput(IDeviceReport report)
        {
            // this should be ordered from least to most chance of having a
            // dependency to another pointer property.
            if (report is IProximityReport proximityReport && Pointer is IHoverDistanceHandler hoverDistanceHandler)
                hoverDistanceHandler.SetHoverDistance(proximityReport.HoverDistance);
            if (report is IEraserReport eraserReport && Pointer is IEraserHandler eraserHandler)
                eraserHandler.SetEraser(eraserReport.Eraser);
            if (report is ITiltReport tiltReport && Pointer is ITiltHandler tiltHandler && !DisableTilt)
                tiltHandler.SetTilt(tiltReport.Tilt);
            if (report is ITabletReport tabletReport && Pointer is IPressureHandler pressureHandler &&
                !DisablePressure && Tablet?.Properties.Specifications.Pen != null)
                pressureHandler.SetPressure(tabletReport.Pressure / (float)Tablet.Properties.Specifications.Pen.MaxPressure);

            // make sure to set the position last
            if (Pointer != null && report is IAbsolutePositionReport absReport)
                Pointer.SetPosition(absReport.Position);
            if (Pointer is ISynchronousPointer synchronousPointer)
            {
                if (report is OutOfRangeReport)
                    synchronousPointer.Reset();
                synchronousPointer.Flush();
            }
        }
    }
}
