        protected override void QueuePendingPositionFromSystem()
        {
            QueuePendingPosition(0, 0);
        }

        private static CGPoint GetCursorPosition()
        {
            var eventRef = CGEventCreate(IntPtr.Zero);
            var pos = CGEventGetLocation(eventRef);
            CFRelease(eventRef);
            return pos;
        }
    }
