                );

                eventTap = CoreGraphics.CGEventTapCreate(
                    CoreGraphics.kCGHIDEventTap,
                    CoreGraphics.kCGHeadInsertEventTap,
                    CoreGraphics.kCGEventTapOptionDefault,
                    mask,
                    eventTapCallback,
                    GCHandle.ToIntPtr(gcHandle)
                );

                if (eventTap == IntPtr.Zero)
