            var dst = Path.Join(AppInfo.Current.AppDataDirectory, dstFileName);

            Log.Write("MoveSettingsFile", $"Moving settings file at '{src}' to '{dst}'", LogLevel.Debug);
            File.Move(src, dst);
        }

