        [Fact]
        public void BluetoothParserParsesStandardBlePenReport()
        {
            var parser = new WH851BluetoothReportParser();

            var report = parser.Parse(
            [
                0x0a,
                0x40 | 0x02,
                0x34, 0x12,
                0x78, 0x56,
                0xbc, 0x0a,
                0xfe,
                0x05
            ]);

