            return type.IsPrimitive ||
                   type.IsEnum ||
                   type == typeof(string) ||
                   type == typeof(decimal) ||
                   type == typeof(DateTime) ||
                   type == typeof(TimeSpan) ||
                   type == typeof(JToken) ||
                   type.IsSubclassOf(typeof(JToken));
        }

        private void ScheduleSave()
        {
            if (disposed || settings == null)
                return;

            CancellationTokenSource cts;
            lock (gate)
            {
                CancelDebounce();
                debounce = cts = new CancellationTokenSource();
            }

            _ = Task.Run(async () =>
            {
                try
                {
                    await Task.Delay(debounceDelay, cts.Token);
                    await FlushCore(cts.Token);
                }
                catch (OperationCanceledException)
                {
                }
                catch (Exception ex)
                {
                    Log.Exception(ex);
                }
            });
        }

        private async Task FlushCore(CancellationToken token)
        {
            if (disposed || settings == null || token.IsCancellationRequested)
                return;

            await flushLock.WaitAsync(token);
            try
            {
                if (disposed || settings == null || token.IsCancellationRequested)
                    return;

                var file = settingsFileProvider();
                if (file.DirectoryName != null)
                    Directory.CreateDirectory(file.DirectoryName);

                settings.Serialize(file);
                await applySettings(settings);
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                Log.Exception(ex);
            }
            finally
            {
                flushLock.Release();
            }
        }

        private void CancelDebounce()
        {
            debounce?.Cancel();
            debounce?.Dispose();
            debounce = null;
        }

        public void Dispose()
        {
            disposed = true;
            CancelDebounce();

            foreach (var unsubscribe in subscriptions)
                unsubscribe();

            subscriptions.Clear();
            observed.Clear();
            flushLock.Dispose();
        }
    }
